"use client";

import "../../styles/teum-base.css";
import "../../styles/components/context-menu.css";
import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";
import { Check } from "@phosphor-icons/react";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export const ContextMenu = ContextMenuPrimitive.Root;

export function ContextMenuTrigger({ className, ...props }: ContextMenuPrimitive.Trigger.Props) {
  return <ContextMenuPrimitive.Trigger className={cn("teum-context-menu__trigger", className)} {...props} />;
}

export type ContextMenuContentProps = ContextMenuPrimitive.Popup.Props &
  Pick<ContextMenuPrimitive.Positioner.Props, "align" | "alignOffset" | "collisionAvoidance" | "side" | "sideOffset">;

export function ContextMenuContent({ className, align = "start", alignOffset = 0, collisionAvoidance, side = "bottom", sideOffset = 4, ...props }: ContextMenuContentProps) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner className="teum-positioner" align={align} alignOffset={alignOffset} collisionAvoidance={collisionAvoidance} side={side} sideOffset={sideOffset}>
        <ContextMenuPrimitive.Popup className={cn("teum-menu teum-context-menu", className)} data-layer="flyout" {...props} />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}

export function ContextMenuLabel({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div role="presentation" className={cn("teum-menu__label", className)} {...props} />;
}

export function ContextMenuItem({ className, ...props }: ContextMenuPrimitive.Item.Props) {
  return <ContextMenuPrimitive.Item className={cn("teum-menu__item", className)} {...props} />;
}

export function ContextMenuSeparator(props: ContextMenuPrimitive.Separator.Props) {
  return <ContextMenuPrimitive.Separator className="teum-menu__separator" {...props} />;
}

export function ContextMenuCheckboxItem({ className, children, ...props }: ContextMenuPrimitive.CheckboxItem.Props) {
  return (
    <ContextMenuPrimitive.CheckboxItem className={cn("teum-menu__item teum-menu__item--check", className)} {...props}>
      <span>{children}</span>
      <ContextMenuPrimitive.CheckboxItemIndicator className="teum-menu__check"><Check weight="bold" /></ContextMenuPrimitive.CheckboxItemIndicator>
    </ContextMenuPrimitive.CheckboxItem>
  );
}

export const ContextMenuRadioGroup = ContextMenuPrimitive.RadioGroup;

export function ContextMenuRadioItem({ className, children, closeOnClick = true, ...props }: ContextMenuPrimitive.RadioItem.Props) {
  return (
    <ContextMenuPrimitive.RadioItem className={cn("teum-menu__item teum-menu__item--check", className)} closeOnClick={closeOnClick} {...props}>
      <span>{children}</span>
      <ContextMenuPrimitive.RadioItemIndicator className="teum-menu__check"><Check weight="bold" /></ContextMenuPrimitive.RadioItemIndicator>
    </ContextMenuPrimitive.RadioItem>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-positioner { z-index: var(--teum-layer-flyout); }

.teum-menu kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; color: var(--teum-ink-tertiary); font-family: inherit; font-size: 10px; line-height: 1; white-space: nowrap; }

.teum-menu { min-width: 196px; max-height: var(--available-height); padding: 4px; overflow: auto; border-radius: var(--teum-radius-overlay); background: var(--teum-bg-flyout); box-shadow: var(--teum-shadow-flyout); outline: 0; transform-origin: var(--transform-origin); transition: opacity 150ms var(--teum-ease-out), transform 150ms var(--teum-ease-out); }

.teum-menu[data-starting-style] { opacity: 0; transform: translateY(-2px) scale(0.985); }

.teum-menu[data-ending-style] { opacity: 0; transform: translateY(-1px) scale(0.99); transition-duration: 100ms; }

.teum-menu__label { padding: 6px 7px 4px; color: var(--teum-ink-tertiary); font-size: 11.5px; font-weight: 560; letter-spacing: 0.02em; }

.teum-menu__item { display: flex; min-height: var(--teum-row-height-menu); align-items: center; gap: 7px; padding: 0 7px; border-radius: calc(var(--teum-radius-control) - 1px); outline: 0; color: var(--teum-ink); font-size: 13px; cursor: default; user-select: none; }

.teum-menu__item svg { width: 13px; height: 13px; color: var(--teum-fg-muted); }

.teum-menu__item kbd { margin-left: auto; }

.teum-menu__item[data-highlighted] { background: var(--teum-hover); color: var(--teum-ink); }

.teum-menu__item[data-disabled] { opacity: 0.4; }

.teum-menu__item--check { justify-content: space-between; }

.teum-menu__check { display: inline-flex; }

.teum-menu__check svg { width: 11px; height: 11px; color: currentColor; }

.teum-menu__separator { height: 1px; margin: 4px; background: var(--teum-border-subtle); }

.teum-menu {
  scrollbar-color: var(--teum-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.teum-menu::-webkit-scrollbar { width: 10px; height: 10px; }

.teum-menu::-webkit-scrollbar-track { background: transparent; }

.teum-menu::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--teum-scrollbar-thumb);
  background-clip: padding-box;
}

.teum-menu::-webkit-scrollbar-thumb:hover { background: var(--teum-scrollbar-thumb-hover); background-clip: padding-box; }

:root[data-theme="dark"] .teum-menu__item svg,
:root[data-theme="dark"] .teum-menu__check svg { color: var(--teum-ink); }

.teum-menu__check {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--teum-ease-out), transform 140ms var(--teum-ease-out);
}

@starting-style {
.teum-menu__check {
    opacity: 0;
    transform: scale(.72);
  }
}

.teum-menu { background: var(--teum-bg-flyout); }

@media (forced-colors: active) {
.teum-menu { scrollbar-color: auto; }
}

@media (prefers-reduced-motion: reduce) {
.teum-menu {
    transition-property: opacity;
    transition-duration: var(--teum-exit-duration);
  }

.teum-menu[data-starting-style],
.teum-menu[data-ending-style] { transform: none; }

.teum-menu__check { transition-duration: 0.01ms; }
}

.teum-context-menu__trigger { outline: 0; touch-action: manipulation; }

.teum-context-menu { min-width: 188px; }
}
